from itertools import product, combinations
from collections import Counter


def _temporal(data, exact, minimum):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    start = data["start"]
    initial_mask = bit.get(source, 0)
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    initial = (source, initial_mask, 0)
    dist = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, spent = heapq.heappop(queue)
        state = (node, mask, spent)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and (not exact or spent == coupons):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for use in (0, 1):
                if use and spent >= coupons:
                    continue
                duration = edge["duration"]
                if use:
                    duration = max(minimum, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = (edge["v"], mask | bit.get(edge["v"], 0), spent + use)
                if arrival < dist.get(nxt, float("inf")):
                    dist[nxt] = arrival
                    heapq.heappush(queue, (arrival, *nxt))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    def rounded(n, mode):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax = rounded(net * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    candidates = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        candidates.append([-1] + sorted(versions))

    best_vector = None
    best = None
    for vector in product(*candidates):
        installed = {name: version for name, version in zip(names, vector) if version != -1}
        if any(name not in installed or not low <= installed[name] <= high
               for name, (low, high) in roots.items()):
            continue
        edges = {name: [] for name in installed}
        valid = True
        for name, version in installed.items():
            row = next(row for row in packages[name] if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in installed or not dep["min"] <= installed[target] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue
        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = installed
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None
    best_total = None
    for subset in combinations(available, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        valid = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            heapq.heappush(active, job["end"])
            if len(active) > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids, best_total = value, sorted_ids, value
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_total}


